def issue_refund(order_id, amount, reason):
    # do not touch payments yet, ask a human first
    request_id = create_approval_request(
        action="issue_refund",
        details={"order_id": order_id, "amount": amount, "reason": reason},
    )
    return {
        "status": "pending",
        "request_id": request_id,
        "message": f"Waiting for approval before refunding {amount} on order {order_id}",
    }

def resume_after_decision(request_id):
    decision = get_approval_decision(request_id)

    if decision.status == "approved":
        details = decision.details
        result = process_refund(details["order_id"], details["amount"])
        return {"status": "completed", "result": result}

    if decision.status == "rejected":
        return {"status": "cancelled", "reason": decision.note}

    return {"status": "pending"}
